import { useRef, type KeyboardEvent } from "react";
import "./AccentPicker.css";

export type Accent = "myelin" | "emerald" | "amber" | "rose";

interface AccentOption {
  readonly id: Accent;
  readonly label: string;
}

const OPTIONS: readonly AccentOption[] = [
  { id: "myelin", label: "Myelin blue" },
  { id: "emerald", label: "Emerald" },
  { id: "amber", label: "Amber" },
  { id: "rose", label: "Rose" },
];

export interface AccentPickerProps {
  value: Accent;
  onChange: (accent: Accent) => void;
}

export function AccentPicker({ value, onChange }: AccentPickerProps) {
  const buttonRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const selectedIndex = Math.max(
    0,
    OPTIONS.findIndex((option) => option.id === value),
  );

  function selectIndex(index: number) {
    const option = OPTIONS[index];
    if (!option) return;
    onChange(option.id);
    buttonRefs.current[index]?.focus();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    let next: number;
    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        next = (index + 1) % OPTIONS.length;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        next = (index - 1 + OPTIONS.length) % OPTIONS.length;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = OPTIONS.length - 1;
        break;
      default:
        return;
    }
    event.preventDefault();
    selectIndex(next);
  }

  return (
    <div role="radiogroup" aria-label="Accent colour" className="accent-picker">
      {OPTIONS.map((option, index) => {
        const checked = option.id === value;
        return (
          <button
            key={option.id}
            ref={(element) => {
              buttonRefs.current[index] = element;
            }}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={index === selectedIndex ? 0 : -1}
            className="accent-picker__option"
            data-accent={option.id}
            onClick={() => onChange(option.id)}
            onKeyDown={(event) => handleKeyDown(event, index)}
          >
            <span className="accent-picker__swatch" aria-hidden="true" />
            <span className="accent-picker__label">{option.label}</span>
            {checked && (
              <svg
                className="accent-picker__mark"
                viewBox="0 0 16 16"
                aria-hidden="true"
                focusable="false"
              >
                <path d="M3.5 8.5l3 3 6-7" />
              </svg>
            )}
          </button>
        );
      })}
    </div>
  );
}
