/*
 * Swatch colours come from per-accent tokens: --accent-myelin, --accent-emerald,
 * --accent-amber and --accent-rose. The theme stylesheet defines them with the
 * day and night values from the token list, so this file never names a colour.
 */

.accent-picker {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.accent-picker__option {
  font: inherit;
  font-size: clamp(0.875rem, 0.6rem + 0.9vw, 1rem);
  display: inline-flex;
  align-items: center;
  gap: 0.5em;
  padding: 0.5em 0.9em 0.5em 0.6em;
  border: 1px solid var(--muted);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition:
    background-color 150ms ease,
    border-color 150ms ease;
}

.accent-picker__option:hover {
  background: var(--code-bg);
}

.accent-picker__option[aria-checked="true"] {
  border-color: var(--myelin);
  background: var(--myelin-wash);
  font-weight: 600;
}

.accent-picker__swatch {
  flex: none;
  width: 0.9em;
  height: 0.9em;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px var(--hair);
}

.accent-picker__option[data-accent="myelin"] .accent-picker__swatch {
  background: var(--accent-myelin);
}

.accent-picker__option[data-accent="emerald"] .accent-picker__swatch {
  background: var(--accent-emerald);
}

.accent-picker__option[data-accent="amber"] .accent-picker__swatch {
  background: var(--accent-amber);
}

.accent-picker__option[data-accent="rose"] .accent-picker__swatch {
  background: var(--accent-rose);
}

.accent-picker__label {
  white-space: nowrap;
}

.accent-picker__mark {
  flex: none;
  width: 0.9em;
  height: 0.9em;
  fill: none;
  stroke: var(--myelin);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

:root[data-motion="reduce"] .accent-picker__option {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .accent-picker__option {
    transition: none;
  }
}
```

The swatches read four per-accent variables (`--accent-myelin`, `--accent-emerald`, `--accent-amber`, `--accent-rose`). The token list only exposes the accent that is currently active, so the theme stylesheet needs to define these four with the day and night values from the token file.

